from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class PlanUpdateResponseV1(SchemaObject):
    finished = SchemaField(name="finished")
    planId = SchemaField(name="resp.planId", optional=True)
    operationId = SchemaField(name="resp.operation.id", optional=True)

    def __init__(self, planId=None, operationId=None, finished=True):
        self.planId = planId
        self.operationId = operationId
        self.finished = finished

        super(PlanUpdateResponseV1, self).__init__()
